from collections import deque

def shortest_path_unweighted(graph, start, goal):
    queue = deque([(start, [start])])
    seen = {start}
    while queue:
        node, path = queue.popleft()
        if node == goal:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

def has_cycle_directed(graph):
    visiting = set()
    visited = set()
    nodes = set(graph)
    for neighbors in graph.values():
        nodes.update(neighbors)

    def visit(node):
        if node in visiting:
            return True
        if node in visited:
            return False
        visiting.add(node)
        for neighbor in graph.get(node, []):
            if visit(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    return any(visit(node) for node in nodes)

import heapq

def dependency_order(dependencies):
    nodes = set(dependencies)
    for deps in dependencies.values():
        nodes.update(deps)
    outgoing = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}
    for item, deps in dependencies.items():
        for dep in deps:
            outgoing[dep].append(item)
            indegree[item] += 1
    ready = [node for node, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    out = []
    while ready:
        node = heapq.heappop(ready)
        out.append(node)
        for neighbor in sorted(outgoing[node]):
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(ready, neighbor)
    if len(out) != len(nodes):
        raise ValueError("cycle")
    return out

def reverse_adjacency(graph):
    nodes = set(graph)
    incoming = {node: [] for node in nodes}
    for node, neighbors in graph.items():
        for neighbor in neighbors:
            nodes.add(neighbor)
            incoming.setdefault(neighbor, []).append(node)
    for node in nodes:
        incoming.setdefault(node, [])
    return {node: sorted(values) for node, values in sorted(incoming.items())}

