def redact_ipv4_last_octet(text):
    def repl(match):
        parts = [int(group) for group in match.groups()]
        if all(0 <= part <= 255 for part in parts):
            return f"{parts[0]}.{parts[1]}.{parts[2]}.x"
        return match.group(0)

