def collapse_ranges(values):
    nums = sorted(set(values))
    if not nums:
        return []
    ranges = []
    start = prev = nums[0]
    for value in nums[1:]:
        if value == prev + 1:
            prev = value
        else:
            ranges.append((start, prev))
            start = prev = value
    ranges.append((start, prev))
    return ranges

